/// Runs a configured command with the run's placeholders and captures its output under
/// `<run_dir>/tmp`. The error names the command, its exit and the last stderr line.
async fn run_command(
    config: &LoadedConfig,
    label: &str,
    command: &[String],
    run_id: &str,
    run_dir: &Path,
    timeout: Duration,
) -> Result<Finished> {
